package com.sakib.portebo.ui;
import android.os.Bundle;import android.view.Gravity;import android.view.View;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.Nullable;import androidx.appcompat.app.AppCompatActivity;import com.google.android.material.button.MaterialButton;import com.google.android.material.card.MaterialCardView;import com.sakib.portebo.R;import com.sakib.portebo.message.MessageManager;import com.sakib.portebo.update.UpdateManager;import com.sakib.portebo.util.BengaliDateFormat;import java.util.List;
public class NotificationsActivity extends PaletteActivity{private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}@Override protected void onCreate(@Nullable Bundle b){super.onCreate(b);MessageManager.markAllAsRead(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(getColor(R.color.bg_app));root.setPadding(dp(16),dp(12),dp(16),dp(16));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView back=new TextView(this);back.setText("‹");back.setTextSize(32);back.setTextColor(getColor(R.color.text_primary));back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(44),dp(48)));TextView title=new TextView(this);title.setText("নোটিফিকেশন");title.setTextColor(getColor(R.color.text_primary));title.setTextSize(20);title.setTypeface(null,1);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));List<MessageManager.MessageItem> items=MessageManager.getHistory(this);if(items.isEmpty()){TextView empty=new TextView(this);empty.setText("এখন কোনো নোটিফিকেশন নেই।");empty.setTextColor(getColor(R.color.text_secondary));empty.setGravity(Gravity.CENTER);list.addView(empty,new LinearLayout.LayoutParams(-1,dp(220)));}else for(MessageManager.MessageItem item:items)list.addView(card(item));setContentView(root);}
private boolean isUpdate(String id){return id!=null&&id.startsWith("release_");}private String version(String id){if(id==null)return "";String s=id.startsWith("release_")?id.substring(8):id;return s.startsWith("v")||s.startsWith("V")?s:"v"+s;}private int compare(String a,String b){try{String[] x=a.replaceFirst("^[vV]","").split("\\."),y=b.replaceFirst("^[vV]","").split("\\.");for(int i=0;i<Math.max(x.length,y.length);i++){int q=i<x.length?Integer.parseInt(x[i]):0,r=i<y.length?Integer.parseInt(y[i]):0;if(q!=r)return q>r?1:-1;}return 0;}catch(Exception e){return a.compareTo(b);}}
private View card(MessageManager.MessageItem item){MaterialCardView card=new MaterialCardView(this);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);card.setLayoutParams(cp);card.setRadius(dp(20));card.setCardElevation(dp(2));card.setStrokeWidth(dp(1));card.setStrokeColor(getColor(R.color.border_subtle));card.setCardBackgroundColor(getColor(R.color.bg_card));LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(14),dp(16),dp(14));card.addView(box);boolean release=isUpdate(item.id);TextView time=new TextView(this);time.setText(BengaliDateFormat.format(item.date));time.setTextColor(getColor(R.color.text_secondary));time.setTextSize(12);box.addView(time);TextView heading=new TextView(this);heading.setText(release?"New version found":item.title);heading.setTextColor(getColor(R.color.text_primary));heading.setTextSize(16);heading.setTypeface(null,1);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=dp(6);box.addView(heading,hp);if(release){TextView ver=new TextView(this);ver.setText(version(item.id));ver.setTextColor(getColor(R.color.text_secondary));ver.setTextSize(12);box.addView(ver);TextView details=new TextView(this);details.setVisibility(View.GONE);details.setText("Running version: "+UpdateManager.getCurrentVersionName(this)+"\nNew version: "+version(item.id)+"\nUpdated: "+item.content);details.setTextColor(getColor(R.color.text_secondary));details.setTextSize(13);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,-2);dp.topMargin=dp(8);box.addView(details,dp);card.setOnClickListener(v->details.setVisibility(details.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));MaterialButton action=new MaterialButton(this);boolean newer=compare(version(item.id),UpdateManager.getCurrentVersionName(this))>0;action.setText(newer?"Update":"Updated ✓");action.setEnabled(newer);action.setOnClickListener(v->UpdateManager.downloadAndInstall(this,null,(ok,msg,url)->Toast.makeText(this,msg,Toast.LENGTH_LONG).show()));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-2,dp(42));ap.topMargin=dp(8);box.addView(action,ap);}else{TextView body=new TextView(this);body.setText(item.content);body.setTextColor(getColor(R.color.text_secondary));body.setTextSize(14);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(6);box.addView(body,bp);}return card;}}
